// Command codemap generates a package-level "code map" for AI agents.
//
// It produces a deterministic routing index (.ai/codemap.md) describing every
// Go package in the module: its purpose (from the package doc comment), file
// counts, internal dependencies, and key exported symbols.
//
// The map is a router, not documentation: an agent reads it to decide which
// files to open, then opens only those. It is regenerated by `make codemap`
// and should not be hand-edited. Author intent notes in .ai/codemap.notes.md.
//
// Usage: go run ./hack/codemap [-out .ai/codemap.md] [-max-symbols 30]
package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

type pkg struct {
	ImportPath  string
	Name        string
	Doc         string
	Dir         string
	GoFiles     []string
	TestGoFiles []string
	Imports     []string
}

func main() {
	out := flag.String("out", ".ai/codemap.md", "output file path")
	maxSymbols := flag.Int("max-symbols", 30, "max symbols listed per package")
	flag.Parse()

	module, err := run("go", "list", "-m")
	if err != nil {
		fatal("go list -m: %v", err)
	}
	module = strings.TrimSpace(module)

	sha, _ := run("git", "rev-parse", "--short", "HEAD")
	sha = strings.TrimSpace(sha)
	if sha == "" {
		sha = "unknown"
	}

	pkgs, err := listPackages()
	if err != nil {
		fatal("listing packages: %v", err)
	}

	// Filter out the codemap tool itself and fully-generated packages, then sort.
	var kept, generated []pkg
	for _, p := range pkgs {
		rel := relPath(p.ImportPath, module)
		if rel == "hack/codemap" {
			continue
		}
		if isGenerated(p) {
			generated = append(generated, p)
			continue
		}
		kept = append(kept, p)
	}
	byPath := func(s []pkg) { sort.Slice(s, func(i, j int) bool { return s[i].ImportPath < s[j].ImportPath }) }
	byPath(kept)
	byPath(generated)

	var b strings.Builder
	writeHeader(&b, module, sha, len(kept), len(generated))
	writeIndex(&b, kept, module)
	writeDetails(&b, kept, module, *maxSymbols)
	writeGenerated(&b, generated, module)

	if dir := filepath.Dir(*out); dir != "" {
		if err := os.MkdirAll(dir, 0o755); err != nil {
			fatal("mkdir %s: %v", dir, err)
		}
	}
	if err := os.WriteFile(*out, []byte(b.String()), 0o644); err != nil {
		fatal("writing %s: %v", *out, err)
	}
	fmt.Printf("wrote %s (%d packages)\n", *out, len(kept))
}

func writeHeader(b *strings.Builder, module, sha string, n, gen int) {
	fmt.Fprintf(b, "# Code Map — `%s`\n\n", module)
	fmt.Fprintf(b, "> Generated by `make codemap` on %s at commit `%s` — %d packages (%d generated, listed at end).\n",
		time.Now().UTC().Format("2006-01-02"), sha, n, gen)
	b.WriteString("> Do not hand-edit: this file is regenerated. Add human/agent intent notes to `.ai/codemap.notes.md`.\n\n")
	b.WriteString("**How to use:** Skim the Package Index to find the area you need, then jump to that package's ")
	b.WriteString("section for its key symbols and files. Open only those files — do not scan the tree.\n\n")
}

func writeIndex(b *strings.Builder, pkgs []pkg, module string) {
	b.WriteString("## Package Index\n\n")
	b.WriteString("| Package | Purpose |\n|---|---|\n")
	for _, p := range pkgs {
		rel := relPath(p.ImportPath, module)
		purpose := synopsis(p.Doc)
		if purpose == "" {
			purpose = "_(no package doc)_"
		}
		fmt.Fprintf(b, "| [`%s`](#%s) | %s |\n", rel, anchor(rel), escapeCell(purpose))
	}
	b.WriteString("\n")
}

func writeDetails(b *strings.Builder, pkgs []pkg, module string, maxSymbols int) {
	b.WriteString("## Packages\n\n")
	for _, p := range pkgs {
		rel := relPath(p.ImportPath, module)
		fmt.Fprintf(b, "### `%s`\n\n", rel)
		if s := synopsis(p.Doc); s != "" {
			fmt.Fprintf(b, "%s\n\n", s)
		}
		fmt.Fprintf(b, "- Files: %d source, %d test\n", len(p.GoFiles), len(p.TestGoFiles))

		deps := internalDeps(p.Imports, module)
		if len(deps) > 0 {
			fmt.Fprintf(b, "- Internal deps: %s\n", strings.Join(deps, ", "))
		}

		syms := symbols(p.ImportPath, maxSymbols)
		if len(syms) > 0 {
			b.WriteString("- Key symbols:\n")
			for _, s := range syms {
				fmt.Fprintf(b, "  - `%s`\n", s)
			}
		}
		b.WriteString("\n")
	}
}

func writeGenerated(b *strings.Builder, pkgs []pkg, module string) {
	if len(pkgs) == 0 {
		return
	}
	b.WriteString("## Generated packages\n\n")
	b.WriteString("Auto-generated (all files `*.gen.go`); regenerated by `make generate-api`. ")
	b.WriteString("Do not edit; edit the OpenAPI spec instead.\n\n")
	for _, p := range pkgs {
		fmt.Fprintf(b, "- `%s`\n", relPath(p.ImportPath, module))
	}
	b.WriteString("\n")
}

// isGenerated reports whether every source file in the package is generated
// (ends in .gen.go). Such packages are OpenAPI clients/servers not worth
// detailing in the routing index.
func isGenerated(p pkg) bool {
	if len(p.GoFiles) == 0 {
		return false
	}
	for _, f := range p.GoFiles {
		if !strings.HasSuffix(f, ".gen.go") {
			return false
		}
	}
	return true
}

func listPackages() ([]pkg, error) {
	cmd := exec.Command("go", "list", "-json", "./...")
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return nil, err
	}
	cmd.Stderr = os.Stderr
	if err := cmd.Start(); err != nil {
		return nil, err
	}
	var pkgs []pkg
	dec := json.NewDecoder(stdout)
	for {
		var p pkg
		if err := dec.Decode(&p); err == io.EOF {
			break
		} else if err != nil {
			return nil, err
		}
		pkgs = append(pkgs, p)
	}
	if err := cmd.Wait(); err != nil {
		return nil, err
	}
	return pkgs, nil
}

// symbols returns cleaned exported signatures from `go doc -short`.
func symbols(importPath string, max int) []string {
	out, err := run("go", "doc", "-short", importPath)
	if err != nil {
		return nil
	}
	var syms []string
	sc := bufio.NewScanner(bytes.NewBufferString(out))
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		// Collapse struct/interface bodies and elided arg lists into concise forms.
		line = strings.ReplaceAll(line, "{ ... }", "")
		line = strings.ReplaceAll(line, " ...", "")
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		syms = append(syms, line)
	}
	if len(syms) > max {
		extra := len(syms) - max
		syms = syms[:max]
		syms = append(syms, fmt.Sprintf("(+%d more)", extra))
	}
	return syms
}

func internalDeps(imports []string, module string) []string {
	seen := map[string]bool{}
	var deps []string
	for _, imp := range imports {
		if !strings.HasPrefix(imp, module+"/") {
			continue
		}
		rel := relPath(imp, module)
		if seen[rel] {
			continue
		}
		seen[rel] = true
		deps = append(deps, "`"+rel+"`")
	}
	sort.Strings(deps)
	return deps
}

func relPath(importPath, module string) string {
	if importPath == module {
		return "."
	}
	return strings.TrimPrefix(importPath, module+"/")
}

func synopsis(doc string) string {
	doc = strings.TrimSpace(doc)
	if doc == "" {
		return ""
	}
	// go list already provides the synopsis (first sentence); keep it single-line.
	return strings.Join(strings.Fields(doc), " ")
}

func anchor(rel string) string {
	a := strings.ToLower(rel)
	a = strings.ReplaceAll(a, "/", "")
	a = strings.ReplaceAll(a, ".", "")
	return a
}

func escapeCell(s string) string {
	return strings.ReplaceAll(s, "|", "\\|")
}

func run(name string, args ...string) (string, error) {
	var buf bytes.Buffer
	cmd := exec.Command(name, args...)
	cmd.Stdout = &buf
	if err := cmd.Run(); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func fatal(format string, args ...any) {
	fmt.Fprintf(os.Stderr, "codemap: "+format+"\n", args...)
	os.Exit(1)
}
